from flask import Flask, redirect

app = Flask(__name__)
@app.get("/")
def index():
    return "Liste"
@app.post("/save")
def save():
    return redirect("/", code=303)

client = app.test_client()
response = client.post("/save")
print(response.status_code)
print(client.post("/save", follow_redirects=True).get_data(as_text=True))

