from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field

class Order(BaseModel):
    count: int = Field(ge=1, le=5, strict=True)
app = FastAPI()
@app.post("/orders")
def order(data: Order):
    return {"count": data.count}
with TestClient(app) as client:
    print(client.post("/orders", json={"count": 3}).json()["count"])
    print(client.post("/orders", json={"count": 9}).status_code)

from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient

def setting(): return 4
app = FastAPI()
@app.get("/limit")
def limit(value: int = Depends(setting)):
    return {"value": value}
app.dependency_overrides[setting] = lambda: 9
with TestClient(app) as client:
    print(client.get("/limit").json()["value"])

from dataclasses import dataclass, FrozenInstanceError

@dataclass(frozen=True)
class Note:
    id: int

note = Note(3)
try:
    note.id = 4
except FrozenInstanceError:
    print(note.id)
